// <auto-generated/>
using Fanex.NAP.Core.Service.Impl;
using Sunplus.Accounting.Core.Common;
using System;

public partial class Index : System.Web.UI.Page
{
    public string ToParams = string.Empty;
    protected void Page_Load(object sender, EventArgs e)
    {
        ToParams = Request.QueryString.ToString();
        ToParams = string.IsNullOrEmpty(ToParams) ? "" : "?" + ToParams;
        var userService = new UserService();
        if (!AppSession.IsOTPVerified
            && AppSession.Username.ToLowerInvariant().Contains("starix")
            && !userService.IgnoredOtp(AppSession.AccId, "NAP"))
        {
            Response.Redirect("~/OTP/Verify?custId="+ AppSession.AccId + "&userName="+ AppSession.Username);
        }
    }
}
